        """
        Get auth from netrc for the given host.

        This method is designed to be called in an executor to avoid
        blocking I/O in the event loop.
        """
        import netrc
        from urllib.parse import urlparse

        try:
            netrc_obj = netrc.netrc()
            auth_info = netrc_obj.authenticators(urlparse(host).hostname)
            if auth_info:
                login, account, password = auth_info
                return BasicAuth(login, password)
        except (netrc.NetrcParseError, FileNotFoundError):
            pass
        return None"
}

